 59	fn merge_scores(
 60	    mps: &[(ParliamentMember, SearchSimilarity)],
 61	    funders: &[(FunderSearchMatch, SearchSimilarity)],
 62	) -> Vec<Entity> {
 63	    let mut scores = Vec::new();
 64	
 65	    let (mut l, mut r) = (0, 0);
 66	    // Unwrap acceptable as index check in
 67	    // while function
 68	    while l < mps.len() && r < funders.len() {
 69	        let mp: &(ParliamentMember, SearchSimilarity) = mps.get(l).unwrap();
 70	        let fund: &(FunderSearchMatch, SearchSimilarity) = funders.get(r).unwrap();
 71	
 72	        match &mp.1.value().total_cmp(&fund.1.value()) {
 73	            std::cmp::Ordering::Equal => {
 74	                scores.push(Entity::from(&mp.0));
 75	                scores.push(Entity::from(&fund.0));
 76	                l += 1;
 77	                r += 1;
 78	            }
 79	            std::cmp::Ordering::Greater => {
 80	                scores.push(Entity::from(&mp.0));
 81	                l += 1;
 82	            }
 83	            std::cmp::Ordering::Less => {
 84	                scores.push(Entity::from(&fund.0));
 85	                r += 1;
 86	            }
 87	        }
 88	    }
 89	    if l < mps.len() {
 90	        for mp in &mps[l..] {
 91	            scores.push(Entity::from(&mp.0));
 92	        }
 93	    }
 94	    if r < funders.len() {
 95	        for fund in &funders[r..] {
 96	            scores.push(Entity::from(&fund.0));
 97	        }
 98	    }
 99	
100	    scores
101	}
